const CONT_CODES = {"af":"ao bf bi bj bw cd cf cg ci cm cv dj dz eg eh er et ga gh gm gn gq gw ke km lr ls ly ma mg ml mr mw mz na ne ng rw sd sl sn so ss st sz td tg tn tz ug za zm zw","as":"ae af am az bd bh bn bt cn ge hk id il in iq ir jo jp kg kh kp kr kw kz la lb lk mm mn mo my np om ph pk ps qa sa sg sy th tj tl tm tr tw uz vn ye","sa":"ar bo br cl co ec fk gy pe py sr uy ve","eu":"ad al at ax ba be bg by ch cy cz de dk ee es fi fo fr gb gg gr hr hu ie im is it je li lt lu lv mc md me mk mt nl no pl pt ro rs ru se si sk sm ua va xk","oc":"as au ck fj fm gu ki mh mp nc nf nr nu nz pf pg pn pw sb to tv vu wf ws","na":"ag ai aw bb bl bm bs bz ca cr cu cw dm do gd gl gt hn ht jm kn ky lc mf ms mx ni pa pm pr sv sx tc tt us vc vg vi"};

// ---- the heat map itself -------------------------------------------------------------------------------------------
// Console players per continent for one weekly report: `players` = tracked console players with a country on their
// profile, `report.playerIndex` = each player's games in that week (id -> { games }). A game counts for every player in
// it, so a game between two continents is counted once on each side.
const CONTINENTS = [
  { key: 'na', label: 'North America', x: 200, y: 112 },
  { key: 'sa', label: 'South America', x: 308, y: 272 },
  { key: 'eu', label: 'Europe', x: 522, y: 84 },
  { key: 'af', label: 'Africa', x: 528, y: 218 },
  { key: 'as', label: 'Asia', x: 742, y: 98 },
  { key: 'oc', label: 'Australia & Oceania', x: 846, y: 306 },
];
const CONT_OF = (() => { const m = {}; Object.entries(CONT_CODES).forEach(([k, s]) => s.split(' ').forEach(c => { m[c] = k; })); return m; })();

function continentWeek(players, report) {
  const pi = (report && report.playerIndex) || {};
  const out = {}; CONTINENTS.forEach(c => { out[c.key] = { players: 0, games: 0, tracked: 0 }; });
  let unknown = 0, total = 0;
  players.forEach(p => {
    const row = pi[String(p.profileId)];
    if (!row) return;
    const g = row.games || 0;
    if (!g) return;
    const k = CONT_OF[String(p.country || '').toLowerCase()];
    if (!k) { unknown += g; return; }
    out[k].players++; out[k].games += g; total += g;
  });
  return { by: out, unknown, total, hasData: Object.keys(pi).length > 0 };
}

function mountContinentMap(root, opts) {
  const { players, dates, fetchReport } = opts;
  let metric = 'games', date = dates[0];
  const cache = new Map();
  const fmt = n => Number(n).toLocaleString();
  const load = d => cache.has(d) ? cache.get(d) : cache.set(d, fetchReport(d).catch(() => null)).get(d);
  root.innerHTML = `
    <div class="wm-controls">
      <select id="wm-week" aria-label="Week">${dates.map((d, i) => `<option value="${d}">${dates[i + 1] ? dates[i + 1] + ' – ' + d : 'Through ' + d}</option>`).join('')}</select>
      <div class="wm-toggle" role="group" aria-label="Heat by">
        <button type="button" data-m="games" class="on">Games played</button><button type="button" data-m="players">Active players</button>
      </div>
    </div>
    <div id="wm-body"><div class="loading">Loading…</div></div>`;
  const body = root.querySelector('#wm-body');

  async function draw() {
    body.innerHTML = '<div class="loading">Loading…</div>';
    const prevDate = dates[dates.indexOf(date) + 1];
    const [rep, prev] = await Promise.all([load(date), prevDate ? load(prevDate) : null]);
    const cur = continentWeek(players, rep);
    if (!cur.hasData) { body.innerHTML = '<p class="weekly-empty">This week\'s report has no per-player game counts, so there is nothing to map. Pick a newer week.</p>'; return; }
    const prv = prev ? continentWeek(players, prev) : null;
    const hasPrev = prv && prv.hasData;
    const vals = CONTINENTS.map(c => cur.by[c.key][metric]);
    const max = Math.max(1, ...vals), sum = vals.reduce((a, b) => a + b, 0) || 1;
    const shade = v => (0.10 + 0.82 * Math.sqrt(v / max)).toFixed(2);   // sqrt so a small continent is still visible next to a big one
    const other = metric === 'games' ? 'players' : 'games';
    const unit = { games: 'games', players: 'players' };
    const labels = CONTINENTS.map(c => {
      const v = cur.by[c.key][metric], o = cur.by[c.key][other];
      return `<g class="wm-lab" transform="translate(${c.x} ${c.y})"><text class="wm-name" y="-17">${c.label}</text><text class="wm-num" y="6">${fmt(v)}</text><text class="wm-sub" y="22">${Math.round(v / sum * 100)}% · ${fmt(o)} ${unit[other]}</text></g>`;
    }).join('');
    const paths = CONTINENTS.map(c => `<path d="${MAP_PATHS[c.key]}" style="fill-opacity:${shade(cur.by[c.key][metric])}"><title>${c.label}: ${fmt(cur.by[c.key].games)} games, ${fmt(cur.by[c.key].players)} players</title></path>`).join('');
    const rows = CONTINENTS.map(c => ({ c, ...cur.by[c.key] })).sort((a, b) => b[metric] - a[metric]).map(r => {
      let chg = '';
      if (hasPrev) {
        const p0 = prv.by[r.c.key][metric], d = r[metric] - p0;
        chg = `<td class="num ${d > 0 ? 'wm-up' : d < 0 ? 'wm-dn' : ''}">${p0 ? (d > 0 ? '▲ +' : d < 0 ? '▼ ' : '') + Math.round(d / p0 * 100) + '%' : '—'}</td>`;
      }
      return `<tr><td>${r.c.label}</td><td class="num">${fmt(r.players)}</td><td class="num">${fmt(r.games)}</td><td class="num">${r.players ? (r.games / r.players).toFixed(1) : '—'}</td><td class="num">${Math.round(r[metric] / sum * 100)}%</td>${hasPrev ? chg : ''}</tr>`;
    }).join('');
    body.innerHTML = `
      <svg class="wm-svg" viewBox="0 0 ${MAP_W} ${MAP_H}" role="img" aria-label="World map shaded by console ${metric} per continent">
        <g class="wm-land">${paths}</g>${labels}
      </svg>
      <div class="wm-legend"><span>fewer</span><i></i><span>more ${metric}</span></div>
      <div class="table-scroll"><table class="wm-table"><thead><tr><th>Continent</th><th class="num">Players</th><th class="num">Games</th><th class="num">Games / player</th><th class="num">Share of ${metric}</th>${hasPrev ? `<th class="num">${metric === 'games' ? 'Games' : 'Players'} vs last week</th>` : ''}</tr></thead><tbody>${rows}</tbody></table></div>
      <p class="wm-note">Counts the console players tracked on this site, placed by the country on their AoE2Companion profile. A game counts once for each player in it, so a game between two continents shows up on both. ${cur.unknown ? `${fmt(cur.unknown)} games by players with no country on their profile (or a country not mapped) are left out.` : ''}</p>`;
  }

  root.querySelector('#wm-week').addEventListener('change', e => { date = e.target.value; draw(); });
  root.querySelector('.wm-toggle').addEventListener('click', e => {
    const b = e.target.closest('button[data-m]'); if (!b) return;
    metric = b.dataset.m;
    root.querySelectorAll('.wm-toggle button').forEach(x => x.classList.toggle('on', x === b));
    draw();
  });
  draw();
}
